def compute(vars):
    trade_names = vars["v1"]
    non_compete_agreements = vars["v2"]
    difference = trade_names - non_compete_agreements

    return {
        "value": difference,
        "trace": {
            "trade_names_gross_carrying_value": trade_names,
            "non_compete_agreements_gross_carrying_value": non_compete_agreements,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
